INSERT INTO content(id,kind,slug,title,published,position,document,updated_at) VALUES('page-home','page','home','Upholstery & Furniture Restoration in Nairobi, Kenya.',1,0,'{"kind":"page","slug":"home","title":"Upholstery & Furniture Restoration in Nairobi, Kenya.","id":"page-home","description":"Explore sofa reupholstery, upholstered beds and headboards, curtains, blinds and cushions. Start with the furniture you have or discuss a new furnishing project with Charles’ Interiors.","body":"","media":[],"position":0,"published":1,"enabled":true,"ctaLabel":"Explore our work","ctaUrl":"/portfolio","featuredHeading":"Materials. Details. Possibilities.","featuredEyebrow":"Selected work","servicesHeading":"Explore our services","servicesEyebrow":"For your space","servicesEnabled":true}','2026-10-27T00:00:00.000Z');
INSERT INTO content(id,kind,slug,title,published,position,document,updated_at) VALUES('page-about','page','about','Furniture and furnishings, considered together',1,0,'{"kind":"page","slug":"about","title":"Furniture and furnishings, considered together","id":"page-about","description":"Charles'' Interiors presents upholstery, furniture restoration and interior furnishing services in Nairobi, Kenya. The work brings seating, upholstered bedroom pieces and window textiles into the same conversation.","body":"## Begin with what you have\n\nAn existing sofa, a bed or a room with changing needs can be the starting point. Discuss what should stay, what is worn and how you want to use the space before choosing a covering or finish.\n\n## A practical furnishing focus\n\nThe range includes bespoke seating, upholstered beds and headboards, cushions, curtains, blinds and automotive seat covers. Each enquiry needs its own scope. Broader design consultancy and specialist work should be confirmed directly.\n\n## Look at the work and ask questions\n\nUse the [portfolio](/portfolio) to view available project photographs, the [service pages](/services) to explore relevant decisions and the [guides](/guides) to understand materials and construction.","media":[],"position":0,"published":1,"enabled":true}','2026-10-27T00:00:00.000Z');
