INSERT INTO content(id,kind,slug,title,published,position,document,updated_at) VALUES('page-process','page','process','Planning your project',1,0,'{"kind":"page","slug":"process","title":"Planning your project","id":"page-process","description":"Start with photographs, dimensions and an idea of the finish you want.","body":"## 1. Share the piece and the context\n\nSend full views, close-ups of wear, approximate measurements and your location. For a room, include windows, existing furniture and anything you want to retain. Avoid including private documents or people in photographs.\n\n## 2. Explain the priorities\n\nDescribe comfort problems, damage, material preferences and intended use. Reference images can communicate a direction; they do not establish that a particular construction or finish is available.\n\n## 3. Confirm the assessment and scope\n\nAsk what can be assessed from photographs and what requires inspection. Confirm material specifications, proposed repairs, final measurements and what the quotation includes.\n\n## 4. Agree the practical arrangements\n\nConfirm price, payment, timing, collection, delivery, fitting and any aftercare instructions directly before committing. These vary by project and are not assumed inclusions.\n\n## 5. Keep the care information\n\nRetain the chosen fabric or material name and its instructions. Report any concern with the agreed work directly, with photographs and a clear description.","media":[],"position":0,"published":1,"enabled":true}','2026-10-27T00:00:00.000Z');
